{
  "name": "ridgewood",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "Ridgewood — a handcrafted 3D colony sim for touch screens.",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build",
    "preview": "vite preview --host 0.0.0.0 --port 3002"
  },
  "dependencies": {
