@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&family=Fraunces:opsz,wght@9..144,500;9..144,600&display=swap');

:root {
  --ink: #f5f0e3;
  --ink-dim: #c2bdaf;
  --ink-faint: #8f8d80;
  --amber: #efb867;
  --amber-deep: #c98a3a;
  --green: #9fc178;
  --green-deep: #5f8a4b;
  --danger: #e2856f;
  --glass: rgba(19, 27, 22, 0.64);
  --glass-strong: rgba(18, 26, 21, 0.9);
  --stroke: rgba(255, 249, 230, 0.1);
  --stroke-bright: rgba(255, 249, 230, 0.18);
  --shadow: 0 16px 40px rgba(5, 10, 7, 0.45);
  --r-lg: 22px;
  --r-md: 16px;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --font: 'Outfit', 'Lato', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --serif: 'Fraunces', Georgia, 'Times New Roman', serif;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0d1410;
  color: var(--ink);
  font-family: var(--font);
  font-weight: 400;
  overscroll-behavior: none;
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
}

#app, #scene, #scene canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
#scene canvas { display: block; touch-action: none; outline: none; }
#ui { position: absolute; inset: 0; pointer-events: none; }
#ui button, #ui .glass, #ui .sheet { pointer-events: auto; }
.hud-layer { position: absolute; }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }

.glass {
  background: linear-gradient(160deg, rgba(34, 45, 36, 0.66), rgba(14, 21, 17, 0.72));
  backdrop-filter: blur(16px) saturate(1.15);
  -webkit-backdrop-filter: blur(16px) saturate(1.15);
  border: 1px solid var(--stroke);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.06);
}
.glass-strong {
  background: linear-gradient(165deg, rgba(30, 41, 33, 0.96), rgba(12, 19, 15, 0.97));
  backdrop-filter: blur(22px) saturate(1.1);
  -webkit-backdrop-filter: blur(22px) saturate(1.1);
  border: 1px solid var(--stroke-bright);
  box-shadow: 0 -20px 60px rgba(3, 8, 5, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

/* ─── top bar ─────────────────────────────────────────── */
#topbar {
  top: 0; left: 0; right: 0;
  padding: calc(10px + var(--safe-top)) 12px 0;
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
  z-index: 40;
}
#colony-id { display: flex; align-items: center; gap: 9px; min-width: 0; flex: 1 1 auto; }
.crest {
  width: 34px; height: 34px; flex: 0 0 34px;
  color: var(--amber);
  filter: drop-shadow(0 2px 8px rgba(239, 184, 103, 0.28));
}
.crest svg { width: 100%; height: 100%; }
.colony-text { min-width: 0; }
.colony-text h1 {
  margin: 0; font-family: var(--serif); font-weight: 600; font-size: 21px;
  letter-spacing: 0.01em; line-height: 1.05;
  color: #fbf6e9; text-shadow: 0 2px 14px rgba(0,0,0,.55);
}
#clock-line {
  display: flex; align-items: center; gap: 5px; margin-top: 2px;
  font-size: 10.5px; letter-spacing: .045em; text-transform: uppercase;
  color: var(--ink-dim); text-shadow: 0 1px 6px rgba(0,0,0,.6);
  white-space: nowrap;
}
#clock-line .dot { color: var(--amber); opacity: .7; }
#top-actions { display: flex; gap: 6px; }
.icon-btn {
  width: 36px; height: 36px; border-radius: 12px;
  display: grid; place-items: center; color: var(--ink-dim);
  transition: color .2s, transform .15s, background .2s;
}
.icon-btn svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.icon-btn:active { transform: scale(.94); background: rgba(255,255,255,.08); }
.icon-btn:hover { color: var(--ink); }
#resource-bar {
  order: 3; width: 100%;
  display: flex; align-items: stretch; justify-content: space-between;
  border-radius: 14px; padding: 5px 4px; gap: 2px;
}
.res {
  flex: 1; min-width: 0; display: flex; align-items: center; justify-content: center; gap: 5px;
  font-size: 12px; font-weight: 500; letter-spacing: .02em; color: #f1ecdf;
  padding: 2px 3px; border-radius: 9px; position: relative;
}
.res + .res::before { content: ''; position: absolute; left: -1px; top: 22%; bottom: 22%; width: 1px; background: rgba(255,255,255,.08); }
.res-val { font-variant-numeric: tabular-nums; transition: color .2s, transform .2s; }
.res.bump .res-val { color: var(--amber); transform: translateY(-1px) scale(1.08); }
.res-icon { width: 17px; height: 17px; flex: 0 0 17px; display: inline-block; position: relative; }
.res-icon.wood::before { content: ''; position: absolute; inset: 3px 1px; border-radius: 4px; background: linear-gradient(150deg, #b9854f, #7d512c); box-shadow: inset 0 -2px 0 rgba(0,0,0,.25); transform: rotate(-14deg); }
.res-icon.wood::after { content: ''; position: absolute; inset: 3px 1px; border-radius: 4px; border: 1px solid rgba(255,225,180,.26); transform: rotate(14deg); }
.res-icon.stone { border-radius: 46% 54% 52% 48%; background: linear-gradient(150deg, #b9b8ae, #74756f); box-shadow: inset -2px -2px 3px rgba(0,0,0,.3), inset 2px 2px 2px rgba(255,255,255,.25); }
.res-icon.food { border-radius: 50% 50% 46% 46%; background: radial-gradient(circle at 35% 30%, #f2d68c, #d09b3f 55%, #92652a); box-shadow: inset -2px -2px 3px rgba(80,40,0,.35); }
.res-icon.food::before { content:''; position:absolute; top:-2px; left:7px; width:2px; height:6px; background:#6f8c4a; border-radius:2px; transform: rotate(18deg); }
.res-icon.silver { border-radius: 50%; background: radial-gradient(circle at 35% 30%, #f4f0dd, #b9b29c 60%, #7f7a68); box-shadow: inset -1px -1px 2px rgba(0,0,0,.4); }
.res-icon.silver::after { content:''; position:absolute; inset:5px; border-radius:50%; border:1px solid rgba(255,255,255,.5); }

/* ─── alerts ─────────────────────────────────────────── */
#alerts { top: calc(104px + var(--safe-top)); left: 0; right: 0; display: flex; flex-direction: column; align-items: center; gap: 5px; z-index: 30; }
.alert {
  display: flex; align-items: center; gap: 6px; padding: 5px 11px 5px 7px;
  border-radius: 20px; font-size: 11px; font-weight: 500; letter-spacing: .02em;
  background: rgba(20, 27, 22, .72); border: 1px solid rgba(255,255,255,.09);
  backdrop-filter: blur(10px); color: var(--ink-dim); pointer-events: auto;
  animation: alertIn .35s cubic-bezier(.2,.9,.25,1.2) both;
}
.alert .a-ic { width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; background: rgba(239,184,103,.14); color: var(--amber); }
.alert .a-ic svg { width: 11px; height: 11px; stroke: currentColor; fill: none; stroke-width: 2; }
.alert.danger { color: #f7d3c7; border-color: rgba(226,133,111,.25); }
.alert.danger .a-ic { background: rgba(226,133,111,.16); color: var(--danger); }
@keyframes alertIn { from { opacity: 0; transform: translateY(-8px) scale(.96); } }

/* ─── colonist dock ───────────────────────────────────── */
#colonist-dock {
  left: 10px; bottom: calc(94px + var(--safe-bottom));
  border-radius: 18px; padding: 5px; z-index: 35; max-width: calc(100vw - 20px);
}
#colonist-strip { display: flex; align-items: center; gap: 4px; }
.col-portrait {
  position: relative; width: 42px; height: 46px; border-radius: 13px;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  transition: background .2s, transform .15s;
}
.col-portrait canvas { width: 30px; height: 30px; border-radius: 50%; box-shadow: 0 2px 6px rgba(0,0,0,.35); }
.col-portrait .cp-mood {
  width: 22px; height: 2px; border-radius: 2px; background: rgba(255,255,255,.12); overflow: hidden;
}
.col-portrait .cp-mood i { display: block; height: 100%; border-radius: 2px; background: var(--green); }
.col-portrait.selected { background: rgba(255,255,255,.1); transform: translateY(-1px); }
.col-portrait.selected::after { content: ''; position: absolute; inset: -1px; border-radius: 13px; border: 1px solid rgba(239,184,103,.45); }
.col-portrait .cp-activity { position: absolute; top: 3px; right: 4px; width: 5px; height: 5px; border-radius: 50%; background: var(--amber); box-shadow: 0 0 6px var(--amber); opacity: 0; }
.col-portrait.working .cp-activity { opacity: 1; animation: pulse 1.6s infinite; }
.col-portrait .cp-sleep { position: absolute; top: 2px; right: 3px; font-size: 8px; color: #b7c8e0; opacity: 0; }
.col-portrait.sleeping .cp-sleep { opacity: 1; }
@keyframes pulse { 50% { opacity: .35; } }

/* ─── selection panel ─────────────────────────────────── */
#selection-panel {
  left: 10px; right: 10px; bottom: calc(94px + var(--safe-bottom));
  margin: 0 auto; max-width: 380px; border-radius: var(--r-lg); padding: 14px;
  z-index: 38; transform-origin: bottom center;
  transition: opacity .22s, transform .26s cubic-bezier(.2,.9,.25,1);
}
#selection-panel.hidden { opacity: 0; transform: translateY(14px) scale(.98); pointer-events: none; }
.sel-head { display: flex; gap: 11px; align-items: center; }
.portrait {
  width: 54px; height: 54px; border-radius: 16px; overflow: hidden; flex: 0 0 54px;
  background: radial-gradient(circle at 50% 30%, #3d4b3c, #1e2820);
  border: 1px solid rgba(255,255,255,.14);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.2);
}
.portrait canvas { width: 100%; height: 100%; display: block; }
.sel-title { min-width: 0; flex: 1; }
.sel-title h2 { margin: 0; font-family: var(--serif); font-size: 19px; font-weight: 600; letter-spacing: .01em; }
.sel-title p { margin: 1px 0 0; font-size: 10.5px; color: var(--ink-faint); letter-spacing: .03em; text-transform: uppercase; }
.mood-row { display: flex; align-items: center; gap: 5px; margin-top: 3px; font-size: 10.5px; color: var(--ink-dim); }
.mood-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px rgba(159,193,120,.7); }
.mini-x { position: absolute; top: 8px; right: 8px; width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; color: var(--ink-faint); font-size: 17px; line-height: 1; }
.mini-x:hover { background: rgba(255,255,255,.08); color: var(--ink); }
.needs { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; margin-top: 12px; }
.need { font-size: 9.5px; letter-spacing: .035em; text-transform: uppercase; color: var(--ink-faint); }
.need .need-top { display: flex; justify-content: space-between; margin-bottom: 3px; }
.need .need-top b { color: var(--ink-dim); font-weight: 500; }
.need-bar { height: 4px; border-radius: 4px; background: rgba(255,255,255,.09); overflow: hidden; }
.need-bar i { display: block; height: 100%; border-radius: 4px; transition: width .4s; }
.need-bar i.high { background: linear-gradient(90deg, #7fae62, #a9c77e); }
.need-bar i.mid { background: linear-gradient(90deg, #ceac5f, #ecc97c); }
.need-bar i.low { background: linear-gradient(90deg, #c46954, #e2856f); }
.sel-activity {
  display: flex; align-items: center; gap: 6px; margin-top: 11px;
  padding: 7px 9px; border-radius: 10px; background: rgba(255,255,255,.045);
  font-size: 11px; color: var(--ink-dim); letter-spacing: .015em;
}
.act-icon { width: 5px; height: 5px; border-radius: 50%; background: var(--amber); box-shadow: 0 0 7px var(--amber); }
.act-icon.idle { background: var(--ink-faint); box-shadow: none; }
.skills { display: flex; gap: 5px; margin-top: 8px; flex-wrap: wrap; }
.skill-chip { font-size: 9.5px; letter-spacing: .03em; color: var(--ink-faint); border: 1px solid rgba(255,255,255,.08); border-radius: 7px; padding: 2px 6px; }
.skill-chip b { color: var(--amber); font-weight: 600; }
.sel-actions { display: flex; gap: 6px; margin-top: 11px; }
.pill-btn {
  flex: 1; font-size: 11px; font-weight: 500; letter-spacing: .02em;
