    this.chipColors = [new THREE.Color(0xb78a55), new THREE.Color(0x8a6138), new THREE.Color(0xd9b37b)];
    this.stoneColors = [new THREE.Color(0xb9b6a8), new THREE.Color(0x8f8f84), new THREE.Color(0xd8d3c0)];
