import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display','utf8').trim();
const browser = await chromium.launch({ ...cfg.browser.launchOptions, headless: false, timeout: 60000 });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
const errs = [];
page.on('pageerror', e => { errs.push(e.message); console.log('PAGEERROR', e.message); });
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForFunction(() => document.body.dataset.ready === 'true', { timeout: 30000 });
await page.waitForTimeout(2500);

// dismiss tutorial
await page.click('#tut-next').catch(()=>{});
await page.waitForTimeout(300);

// tap colonist
const pt = await page.evaluate(() => {
  const g = window.__game;
  const c = g.colony.colonists[1];
  const v = new (g.camera.position.constructor)(c.x, c.y + 0.8, c.z).project(g.camera);
  return { x: (v.x * 0.5 + 0.5) * innerWidth, y: (-v.y * 0.5 + 0.5) * innerHeight, name: c.name };
});
console.log('tap colonist', pt);
await page.mouse.click(pt.x, pt.y);
await page.waitForTimeout(700);
console.log('panel visible', await page.evaluate(() => ({
  hidden: document.querySelector('#selection-panel').classList.contains('hidden'),
  name: document.querySelector('#sel-name').textContent,
  act: document.querySelector('#sel-activity').textContent,
  portrait: (() => { const c=document.querySelector('#sel-portrait canvas'); const d=c.getContext('2d').getImageData(0,0,c.width,c.height).data; let sum=0; for(let i=0;i<d.length;i+=4) sum+=d[i]+d[i+1]+d[i+2]; return sum; })(),
})));
await page.screenshot({ path: '/home/runner/work/Yu/Yu/screenshots/mobile-selected.png' });

// open build sheet
await page.click('.tool[data-tool="build"]');
await page.waitForTimeout(600);
console.log('build sheet open', await page.evaluate(() => ({
  open: document.querySelector('#build-sheet').classList.contains('open'),
  cards: document.querySelectorAll('#build-grid .build-card').length,
})));
await page.screenshot({ path: '/home/runner/work/Yu/Yu/screenshots/mobile-build.png' });

// choose wall card then tap ground
const wall = await page.$('#build-grid [data-build="wall"]');
if (wall) { await wall.click(); await page.waitForTimeout(500); }
const ground = await page.evaluate(() => {
  const g = window.__game;
  const v = new (g.camera.position.constructor)(1.5, 0.1, 5.0).project(g.camera);
  return { x: (v.x * 0.5 + 0.5) * innerWidth, y: (-v.y * 0.5 + 0.5) * innerHeight };
});
await page.mouse.click(ground.x, ground.y);
await page.waitForTimeout(800);
console.log('placement state', await page.evaluate(() => ({
  type: window.__game.placementType,
  valid: window.__game.ghostValid,
  buildings: window.__game.colony.buildings.length,
  blueprints: window.__game.colony.buildings.filter(b=>b.state==='blueprint').length,
})));
await page.screenshot({ path: '/home/runner/work/Yu/Yu/screenshots/mobile-ghost.png' });

// cancel and test speeds
await page.click('#placement-cancel').catch(()=>{});
await page.click('.spd[data-speed="4"]');
await page.waitForTimeout(200);
console.log('speed', await page.evaluate(() => window.__game.colony.speed));

// open log
await page.click('#btn-log');
await page.waitForTimeout(500);
await page.screenshot({ path: '/home/runner/work/Yu/Yu/screenshots/mobile-log.png' });
await page.click('#log-close');

console.log('errors', errs.length);
await browser.close();

