147: export function adjacentTiles(world, tx, tz, radius = 1) {
148:   const out = [];
149:   for (let dz = -radius; dz <= radius; dz++) {
150:     for (let dx = -radius; dx <= radius; dx++) {
151:       if (!radius && !dx && !dz) continue;
152:       if (Math.max(Math.abs(dx), Math.abs(dz)) !== radius && radius > 0) continue;
153:       const nx = tx + dx, nz = tz + dz;
154:       if (world.isWalkable(nx, nz)) out.push({ tx: nx, tz: nz });
155:     }
156:   }
157:   return out;
