  ev('pointermove', 11, 130, 400);
  ev('pointermove', 12, 270, 400); // pinch out
  ev('pointermove', 11, 160, 380);
  ev('pointermove', 12, 300, 380); // drag right
  ev('pointermove', 12, 300, 330); // twist
  ev('pointerup', 11, 160, 380);
  ev('pointerup', 12, 300, 330);
});
