import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display','utf8').trim();
const browser = await chromium.launch({ ...cfg.browser.launchOptions, headless: false, timeout: 60000 });
const page = await browser.newPage({ viewport:{width:390,height:844}, deviceScaleFactor:2, isMobile:true, hasTouch:true });
page.on('pageerror',e=>console.log('PAGEERR',e.message));
await page.goto('http://localhost:3002',{waitUntil:'load'});await page.waitForFunction(()=>document.body.dataset.ready==='true',{timeout:30000});await page.waitForTimeout(1500);
console.log(await page.evaluate(()=>{
  const g=window.__game,c=g.colony;
  c.colonists.forEach(x=>{ if(x.task) x.finishTask(); });
  c.assignBeds();
  return c.colonists.map(x=>{
    const bed=x.bed;
    const spot=bed?{tx:bed.tx,tz:bed.tz+1}:null;
    const walk = spot?g.world.isWalkable(spot.tx,spot.tz):null;
    const ok=x.beginSleep(bed);
    return {n:x.name,bed:bed&&{id:bed.id,tx:bed.tx,tz:bed.tz},spot,walk,ok,taskPhase:x.task?.phase,path:x.path.slice(-3),arrived:x.arrived,atSpot:spot?x.atSpot({spotTiles:spot}):null};
  });
}));
await page.evaluate(()=>window.__game.simulate(8));
console.log(await page.evaluate(()=>window.__game.colony.colonists.map(x=>({n:x.name,phase:x.task?.phase,act:x.activity,tx:x.tx,tz:x.tz,arrived:x.arrived,path:x.path.length,pi:x.pathIndex,spot:x.task?.spotTiles,atSpot:x.task?.spotTiles?x.atSpot(x.task):null}))));
await page.evaluate(()=>window.__game.simulate(8));
console.log(await page.evaluate(()=>window.__game.colony.colonists.map(x=>({n:x.name,phase:x.task?.phase,act:x.activity,tx:x.tx,tz:x.tz,arrived:x.arrived,path:x.path.length,rest:+x.rest.toFixed(1)}))));
await browser.close();

