const cfg = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display','utf8').trim();
const browser = await chromium.launch({ ...cfg.browser.launchOptions, headless: false, timeout: 60000 });
