  const g=window.__game,c=g.colony,w=g.world;
  c.colonists.forEach(x=>{ if(x.task) x.finishTask(); });
  const x=c.colonists.find(x=>x.name==='Ivo');
  const ring=[];
  for(let dz=-2;dz<=2;dz++) for(let dx=-2;dx<=2;dx++){const tx=21+dx,tz=23+dz;ring.push(`${tx},${tz}=${w.isWalkable(tx,tz)?'W':(w.buildingBlocked[w.idx(tx,tz)]?'B':'S')}`)}
