import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display','utf8').trim();
const browser = await chromium.launch({ ...cfg.browser.launchOptions, headless: false, timeout: 60000 });
const page = await browser.newPage({ viewport:{width:390,height:844}, deviceScaleFactor:2, isMobile:true, hasTouch:true });
page.on('pageerror',e=>console.log('PAGEERR',e.message));
await page.goto('http://localhost:3002',{waitUntil:'load'});await page.waitForFunction(()=>document.body.dataset.ready==='true',{timeout:30000});await page.waitForTimeout(1500);
await page.evaluate(()=>{
  const c=window.__game.colony;
  c.colonists.forEach(x=>{ if(x.task) x.finishTask(); });
  const ivo=c.colonists.find(x=>x.name==='Ivo');
  window.__ivo=ivo;
  window.__log=[];
  const orig=ivo.moveTo.bind(ivo);
  ivo.moveTo=(tx,tz,speed)=>{ const r=orig(tx,tz,speed); window.__log.push({call:[tx,tz],from:[ivo.tx,ivo.tz],path:ivo.path.map(p=>[p.tx,p.tz])}); return r; };
  c.startSleepFor(ivo);
  window.__log.push({afterStart:true,task:ivo.task&&{...ivo.task,spotTiles:ivo.task.spotTiles,bed:ivo.task.bed&&{id:ivo.task.bed.id,tx:ivo.task.bed.tx,tz:ivo.task.bed.tz}},path:ivo.path.map(p=>[p.tx,p.tz]),pos:[ivo.x,ivo.z]});
});
for(let i=0;i<12;i++){
  await page.evaluate(()=>window.__game.simulate(1));
  const s=await page.evaluate(()=>{const x=window.__ivo;return {t:+(window.__game.colony.hour).toFixed(2),tx:x.tx,tz:x.tz,x:+x.x.toFixed(2),z:+x.z.toFixed(2),arrived:x.arrived,pi:x.pathIndex,plen:x.path.length,phase:x.task?.phase,atSpot:x.task?.spotTiles?x.atSpot(x.task):null,spot:x.task?.spotTiles};});
  console.log(i+1,JSON.stringify(s));
}
console.log(JSON.stringify(await page.evaluate(()=>window.__log),null,1));
await browser.close();

